with flattened_attrs as (select id, service, level, status_code, payload_json, get_json_object(payload_json, '$.duration') as duration_text, size(context) as num_context, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration as duration_sec, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries as retry_count from app_logs where service != 'billing') select case when retry_count >= 4 then 'PREMIUM' else 'STANDARD' end as retry_count_tier, stddev_samp(status_code) as status_code_stddev, sort_array(collect_set(level)) as level_list, count_if(level = 'ERROR') as error_events, size(collect_set(service)) as num_services from flattened_attrs group by case when retry_count >= 4 then 'PREMIUM' else 'STANDARD' end
